(()=>{'use strict';
 if(!document.body.classList.contains('cafe-integrated'))return;
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 const money=cents=>Number.isFinite(cents)?(cents/100).toLocaleString('ru-RU')+' ₽':'—';
 let dialog=null,button=null,data=null,loading=false,openAfterCard=false,countTimer=0;
 const request=async(url,body)=>{let response;try{response=await fetch(url,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});}catch{throw Object.assign(Error('Связь с сервером прервалась. Повторите тот же запрос.'),{network:true});}let result;try{result=await response.json();}catch{throw Object.assign(Error('Не удалось прочитать ответ сервера.'),{network:true});}if(!response.ok)throw Object.assign(Error(result.error||'Не удалось выполнить запрос.'),{status:response.status,result});return result;};
 const showCount=rows=>{if(button)button.dataset.count=String(rows);};
 async function refreshCount(){if(document.hidden||loading)return;try{const result=await request('/api/admin/cafe/stop-list');showCount(result.items.filter(item=>item.soldOut||item.reasons?.length||item.variants?.some(v=>v.reasons?.length)).length);}catch{}}
 function message(text,error=false){const node=dialog?.querySelector('.csl-message');if(node){node.textContent=text||'';node.dataset.error=String(error);}}
 function close(){if(dialog?.open)dialog.close();dialog?.remove();dialog=null;}
 function detailFor(item){const variantRows=(item.variants||[]).flatMap(variant=>(variant.reasons||[]).map(reason=>({reason,variant:variant.name}))),variantKeys=new Set(variantRows.map(({reason})=>`${reason.code||''}\u0000${reason.message||''}`));return [...(item.reasons||[]).filter(reason=>!variantKeys.has(`${reason.code||''}\u0000${reason.message||''}`)).map(reason=>({reason,variant:null})),...variantRows];}
 function reasonText(reason){return reason?.message||reason?.code||'Доступность не подтверждена';}
 function componentFor(item){const reason=detailFor(item).find(x=>/recipe|short|norm|unit|component/i.test(x.reason.code||''));if(!reason)return 'base';return reason.variant?`variant:${(item.variants||[]).find(v=>v.name===reason.variant)?.id||''}`:'base';}
 function render(){if(!dialog)return;const content=dialog.querySelector('.csl-content');content.replaceChildren();if(!data){content.append(el('p','Загружаю стоп-лист…'));return;}
  if(!data.items.length){content.append(el('p','Блюд с ограничениями нет.'));return;}
  const table=el('table',undefined,'csl-table'),thead=el('thead'),head=el('tr');for(const title of ['Блюдо / вариант','Цена','Доступно','Причина','Действие'])head.append(el('th',title));thead.append(head);table.append(thead);const tbody=el('tbody');
  for(const item of data.items){const row=el('tr');row.dataset.itemId=String(item.id);row.append(el('th',item.name,'csl-product'));row.append(el('td',money(item.priceCents)));row.append(el('td',Number.isFinite(item.available)?String(item.available):'—'));const allReasons=[...(item.reasons||[]),...(item.variants||[]).flatMap(variant=>variant.reasons||[])];
   const reasons=detailFor(item),reasonCell=el('td',undefined,'csl-reasons');if(!reasons.length)reasonCell.append(el('span','Нет доступных позиций'));for(const entry of reasons){const p=el('p',undefined);if(entry.variant)p.append(el('strong',entry.variant+': '));p.append(document.createTextNode(reasonText(entry.reason)));if(entry.reason.inventoryId){const context=el('small','Складская позиция №'+entry.reason.inventoryId);p.append(el('br'),context);}reasonCell.append(p);}row.append(reasonCell);
   const actions=el('td',undefined,'csl-actions');if(item.canResume){const resume=el('button','Снять стоп и заказать','csl-primary');resume.type='button';resume.onclick=()=>postResume(item,resume);actions.append(resume);}
   if(!item.canResume&&allReasons.some(r=>/PACKAGE_UNIT/.test(r.code||''))&&data.canNormalizeUnits){const unitReason=allReasons.find(r=>r.code==='PACKAGE_UNIT'&&Number.isInteger(r.inventoryId));if(unitReason){const normalize=el('button','Учёт в штуках','csl-secondary');normalize.type='button';normalize.onclick=()=>unitForm(item,unitReason,actions);actions.append(normalize);}}
   const hasRecipeFix=!item.canResume&&allReasons.some(r=>/recipe|short|norm|unit|component/i.test(r.code||''));if(hasRecipeFix){const fix=el('button','Исправить расход','csl-secondary');fix.type='button';fix.onclick=()=>openCard(item);actions.append(fix);}
   const settingsCodes=new Set(['NO_ACTIVE_VARIANT','HIDDEN_ITEM','HIDDEN_CATEGORY','MODIFIER_UNAVAILABLE']);if(!hasRecipeFix&&allReasons.some(reason=>settingsCodes.has(reason.code))){const configure=el('button','Настроить товар','csl-secondary');configure.type='button';configure.onclick=()=>openCard(item);actions.append(configure);}
   if(!item.canResume&&allReasons.some(r=>/stock|inventory|available|package_unit/i.test(r.code||''))){const stock=el('a','Остаток','csl-link');stock.href='/admin/purchase/';actions.append(stock);}
   if(item.canOrder){const order=el('button','Заказать','csl-primary');order.type='button';order.onclick=()=>orderProduct(item);actions.append(order);}if(!actions.children.length)actions.append(el('span','Требует проверки'));
   row.append(actions);tbody.append(row);
  }
  table.append(tbody);content.append(table);
 }
 function unitForm(item,reason,actions){actions.replaceChildren();const wrap=el('form',undefined,'csl-unit-form'),label=el('label','Фактически осталось, шт.'),input=el('input');input.type='number';input.min='0';input.step='1';input.inputMode='numeric';input.required=true;input.autocomplete='off';label.append(input);wrap.append(label);const confirmLabel=el('label',undefined,'csl-unit-confirm'),confirm=el('input');confirm.type='checkbox';confirm.checked=false;const confirmText=document.createTextNode('Подтверждаю: числа в нормах означают количество отдельных крышек, стаканов и других предметов, а не целых упаковок');confirmLabel.append(confirm,confirmText);wrap.append(confirmLabel);const save=el('button','Подтвердить','csl-primary');save.type='submit';wrap.append(save);const cancel=el('button','Отмена','csl-secondary');cancel.type='button';cancel.onclick=()=>render();wrap.append(cancel);wrap.onsubmit=async event=>{event.preventDefault();if(!input.value.trim()||!/^\d+$/.test(input.value.trim())){input.focus();return;}if(!confirm.checked){confirm.focus();return;}if(loading)return;loading=true;save.disabled=true;const payload={requestId:crypto.randomUUID(),inventoryId:reason.inventoryId,revision:reason.inventoryRevision,actualCount:input.value.trim(),confirmPieceNorms:true};if(!Number.isInteger(payload.revision)){message('Сервер не передал версию остатка. Обновите стоп-лист.',true);loading=false;save.disabled=false;return;}try{await request('/api/admin/cafe/stock-units',payload);loading=false;await load();}catch(error){loading=false;save.disabled=false;if(error.status===409){message('Остаток изменился. Количество и подтверждение сохранены; обновите данные явно после проверки.',true);save.type='button';save.textContent='Обновить список';save.onclick=async()=>{const count=input.value.trim(),checked=confirm.checked;if(!await load())return;render();const latest=data.items.find(entry=>String(entry.id)===String(item.id)),fresh=latest?.reasons?.find(entry=>entry.code==='PACKAGE_UNIT'&&entry.inventoryId===reason.inventoryId);if(!fresh){message('Ограничение изменилось. Проверьте актуальную причину перед продолжением.',true);return;}const latestRow=[...dialog.querySelectorAll('tbody tr')].find(entry=>entry.dataset.itemId===String(item.id));if(!latestRow)return;const fields=unitForm(latest,fresh,latestRow.lastElementChild);fields.input.value=count;fields.confirm.checked=checked;message('Список обновлён. Проверьте данные и подтвердите повторно.',true);};return;}message(error.message,true);save.type='button';save.textContent='Повторить тот же запрос';save.onclick=()=>retryPost('/api/admin/cafe/stock-units',payload,save);}};actions.append(wrap);input.focus();return{input,confirm};}
 async function retryPost(url,payload,control){if(loading)return;loading=true;control.disabled=true;try{await request(url,payload);loading=false;await load();}catch(error){loading=false;control.disabled=false;message(error.status===409?'Остаток изменился. Введённое количество сохранено; обновите данные явно после проверки.':error.message,true);}}
 async function finishResume(itemId){loading=true;let refreshed;try{refreshed=await request('/api/admin/cafe/stop-list');}finally{loading=false;}data=refreshed;showCount(data.items.filter(item=>item.soldOut||item.reasons?.length||item.variants?.some(v=>v.reasons?.length)).length);const item=data.items.find(row=>String(row.id)===String(itemId));if(!item||item.canOrder){render();await orderProduct({id:itemId});return;}render();const reasons=detailFor(item).map(entry=>reasonText(entry.reason)).filter(Boolean);message('Стоп остался: '+(reasons.join(' · ')||'доступность всё ещё заблокирована')+'. Исправьте указанную причину и обновите список.',true);}
 async function submitResume(itemId,payload,control){if(loading)return;loading=true;control.disabled=true;try{await request('/api/admin/cafe/stop-list',payload);loading=false;await finishResume(itemId);}catch(error){loading=false;control.disabled=false;if(error.status===409){message('Данные изменились. Стоп не снят. Обновите список явно.',true);control.textContent='Обновить список';control.onclick=()=>load();return;}message(error.message,true);control.textContent='Повторить тот же запрос';control.onclick=()=>submitResume(itemId,payload,control);}}
 function postResume(item,control){const payload={requestId:crypto.randomUUID(),revision:data.revision,itemId:item.id,action:'resume'};return submitResume(item.id,payload,control);}
 async function load(){if(!dialog||loading)return false;loading=true;message('Обновляю стоп-лист…');try{data=await request('/api/admin/cafe/stop-list');loading=false;showCount(data.items.filter(item=>item.soldOut||item.reasons?.length||item.variants?.some(v=>v.reasons?.length)).length);render();message('');return true;}catch(error){loading=false;message(error.message,true);return false;}}
 function openCard(item){const card=window.STARTCafeProductCard;if(!card?.open){message('Карточка товара недоступна.',true);return;}openAfterCard=true;close();card.open({id:item.id},{initialComponent:componentFor(item),onSaved:()=>{if(openAfterCard){openAfterCard=false;queueMicrotask(()=>void open());}},onError:error=>{if(openAfterCard){openAfterCard=false;queueMicrotask(()=>void open().then(()=>message(error?.message||'Не удалось открыть карточку товара.',true)));}}});}
 async function ensureComposer(){const screen=document.querySelector('#compose');if(!screen)return;if(screen.hidden){const tab=document.querySelector('[data-tab="compose"]');if(!tab)throw Error('Не удалось открыть оформление заказа.');await new Promise((resolve,reject)=>{let timer;const finish=error=>{clearTimeout(timer);document.removeEventListener('cafe-compose-visibility',visible);if(error)reject(error);else resolve();},visible=event=>{if(event.detail===true)finish();};document.addEventListener('cafe-compose-visibility',visible);timer=setTimeout(()=>finish(Error('Не удалось открыть оформление заказа.')),12000);tab.click();});}await window.cafeComposerReady;}
 async function orderProduct(item){close();try{await ensureComposer();const adapter=window.STARTCafeOrder;if(!adapter?.openProduct)throw Error('Добавление блюда недоступно. Откройте оформление заказа и повторите попытку.');await adapter.openProduct(item.id);}catch(error){await open();message(error.message||'Блюдо недоступно. Обновите список и попробуйте снова.',true);}}
 async function open(){if(dialog?.open){await load();return;}const current=el('dialog',undefined,'cafe-stop-list-dialog');dialog=current;current.setAttribute('aria-labelledby','csl-title');const header=el('header',undefined,'csl-header'),title=el('h2','Блюда в стопе');title.id='csl-title';const refresh=el('button','Обновить','csl-refresh');refresh.type='button';refresh.setAttribute('aria-label','Обновить стоп-лист');refresh.onclick=()=>load();const closeButton=el('button','Закрыть','csl-close');closeButton.type='button';closeButton.onclick=close;header.append(title,refresh,closeButton);const status=el('p','', 'csl-message');status.setAttribute('role','status');const content=el('div',undefined,'csl-content');current.append(header,status,content);current.addEventListener('close',()=>{current.remove();if(dialog===current)dialog=null;});document.body.append(current);current.showModal();data=null;render();await load();}
 function attachButton(node){button=node;if(!countTimer){countTimer=setTimeout(()=>{countTimer=0;void refreshCount();},250);}}
 document.addEventListener('station-updated',()=>{if(dialog?.open)void load();else void refreshCount();});document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(dialog?.open)void load();else void refreshCount();}});
 document.querySelector('#open-stop-list')?.addEventListener('click',()=>void open());
 window.STARTCafeStopList={open,attachButton};
})();
